interface ITemperatur
{
    double Celsius();
}
class FahrenheitAdapter(AltSensor alt)
    : ITemperatur
{
    public double Celsius() =>
        Math.Round(
          (alt.LeseFahrenheit() - 32)
          * 5 / 9, 1);
}
// LeseFahrenheit() liefert 98.6
// Celsius() → 37

interface INachricht
{ string Inhalt(); }
class Text(string t) : INachricht
{ public string Inhalt() => t; }
class Rahmen(INachricht i)
    : INachricht
{ public string Inhalt() =>
    $"[{i.Inhalt()}]"; }
class Gross(INachricht i)
    : INachricht
{ public string Inhalt() =>
    i.Inhalt().ToUpper(); }

INachricht n = new Gross(
    new Rahmen(new Text("hallo")));
Console.WriteLine(n.Inhalt());
// [HALLO]

class Sensor
{
  public event Action<int>?
      WertGeaendert;
  private int wert;
  public void Setze(int neu)
  {
    if (neu == wert) return;
    wert = neu;
    WertGeaendert?.Invoke(neu);
  }
}
var s = new Sensor();
s.WertGeaendert += w =>
    Console.WriteLine($"Anzeige: {w}");
s.WertGeaendert += w =>
    { if (w > 30)
        Console.WriteLine("Alarm!"); };
s.Setze(25); // Anzeige: 25
s.Setze(35); // Anzeige: 35, Alarm!

interface ISortierStrategie
{ List<int> Sortiere(List<int> l); }
class Absteigend : ISortierStrategie
{ public List<int> Sortiere(
    List<int> l) =>
    l.OrderDescending().ToList(); }
class Sortierer(ISortierStrategie s)
{
  public ISortierStrategie Strategie
    { get; set; } = s;
  public List<int> Sortiere(
    List<int> l) =>
    Strategie.Sortiere(l);
}
// [5,3,8] → Absteigend → 8,5,3

